B.amw=new A.S("\u041a\u0443\u0434\u0430 \u0443\u0445\u043e\u0434\u044f\u0442 \u043c\u043e\u0438 \u0444\u043e\u0442\u043e \u0438 \u0434\u0430\u043d\u043d\u044b\u0435?","\u041d\u0438\u043a\u0443\u0434\u0430. \u041a\u0432\u0438\u0442\u043e\u043a \u0440\u0430\u0431\u043e\u0442\u0430\u0435\u0442 \u0431\u0435\u0437 \u0438\u043d\u0442\u0435\u0440\u043d\u0435\u0442\u0430: \u0444\u043e\u0442\u043e \u0440\u0430\u0441\u043f\u043e\u0437\u043d\u0430\u0451\u0442\u0441\u044f \u043d\u0430 \u0442\u0435\u043b\u0435\u0444\u043e\u043d\u0435, \u0438\u0441\u0442\u043e\u0440\u0438\u044f \u0445\u0440\u0430\u043d\u0438\u0442\u0441\u044f \u0442\u043e\u043b\u044c\u043a\u043e \u0437\u0434\u0435\u0441\u044c. \u0424\u0418\u041e, \u0430\u0434\u0440\u0435\u0441 \u0438 \u043b\u0438\u0446\u0435\u0432\u043e\u0439 \u0441\u0447\u0451\u0442 \u043d\u0435 \u0441\u043e\u0445\u0440\u0430\u043d\u044f\u044e\u0442\u0441\u044f.")
B.amv=new A.S("\u041a\u0430\u043a \u043d\u0435 \u043f\u043e\u0442\u0435\u0440\u044f\u0442\u044c \u0438\u0441\u0442\u043e\u0440\u0438\u044e?","\u041d\u0430 Android 10 \u0438 \u043d\u043e\u0432\u0435\u0435 \u041a\u0432\u0438\u0442\u043e\u043a \u0441\u0430\u043c \u043a\u043b\u0430\u0434\u0451\u0442 \u043a\u043e\u043f\u0438\u044e \u0432 \xab\u0417\u0430\u0433\u0440\u0443\u0437\u043a\u0438 \u2192 \u041a\u0432\u0438\u0442\u043e\u043a\xbb. \u041f\u043e\u0441\u043b\u0435 \u043f\u0435\u0440\u0435\u0443\u0441\u0442\u0430\u043d\u043e\u0432\u043a\u0438 - \xab\u041c\u043e\u044f \u0438\u0441\u0442\u043e\u0440\u0438\u044f\xbb \u2192 \xab\u0412\u043e\u0441\u0441\u0442\u0430\u043d\u043e\u0432\u0438\u0442\u044c \u0438\u0437 \u043a\u043e\u043f\u0438\u0438\xbb.")
B.ami=new A.S("\u041a\u0432\u0438\u0442\u043e\u043a \u043e\u0448\u0438\u0431\u0441\u044f \u0432 \u0441\u0442\u0440\u043e\u043a\u0435. \u0427\u0442\u043e \u0434\u0435\u043b\u0430\u0442\u044c?","\u041d\u0430\u0436\u043c\u0438\u0442\u0435 \u043d\u0430 \u0441\u0442\u0440\u043e\u043a\u0443 \u0438 \u0438\u0441\u043f\u0440\u0430\u0432\u044c\u0442\u0435 \u043f\u043e \u0444\u043e\u0442\u043e. \u041d\u0430\u0445\u043e\u0434\u043a\u0438 \u043f\u0435\u0440\u0435\u0441\u0447\u0438\u0442\u0430\u044e\u0442\u0441\u044f \u0441\u0440\u0430\u0437\u0443.")
B.amO=new A.S("\u041d\u0430\u0445\u043e\u0434\u043a\u0430 \u0437\u043d\u0430\u0447\u0438\u0442, \u0447\u0442\u043e \u043c\u0435\u043d\u044f \u043e\u0431\u0441\u0447\u0438\u0442\u0430\u043b\u0438?","\u041d\u0435\u0442. \u042d\u0442\u043e \u043f\u043e\u0432\u043e\u0434 \u0441\u043f\u0440\u043e\u0441\u0438\u0442\u044c \u043e\u0440\u0433\u0430\u043d\u0438\u0437\u0430\u0446\u0438\u044e. \u041e\u0448\u0438\u0431\u043a\u0430 \u043c\u043e\u0436\u0435\u0442 \u0431\u044b\u0442\u044c \u0438 \u0432 \u0440\u0430\u0441\u043f\u043e\u0437\u043d\u0430\u0432\u0430\u043d\u0438\u0438, \u0438 \u0437\u0430\u043a\u043e\u043d\u043d\u0430\u044f \u043f\u0440\u0438\u0447\u0438\u043d\u0430 - \u043d\u0430\u043f\u0440\u0438\u043c\u0435\u0440, \u043f\u0435\u0440\u0435\u0440\u0430\u0441\u0447\u0451\u0442 \u0437\u0430 \u043f\u0440\u043e\u0448\u043b\u044b\u0435 \u043c\u0435\u0441\u044f\u0446\u044b.")
